def decode_percent(text):
    mapping = {'20': ' ', '2F': '/', '25': '%'}
    result = ''
    index = 0
    while index < len(text):
        code = text[index + 1:index + 3].upper() if text[index:index + 1] == '%' else ''
        if code in mapping:
            result += mapping[code]
            index += 3
        else:
            result += text[index]
            index += 1
    return result

